param([Parameter(Mandatory = $true)][string]$Target)

$ErrorActionPreference = 'Stop'

function Get-Value([string]$Name, [string]$Default = '') {
    $value = [Environment]::GetEnvironmentVariable($Name)
    if ($null -eq $value) { return $Default }
    return $value
}

function TomlQuote([string]$Value) {
    if ($null -eq $Value) { $Value = '' }
    $Value = $Value.Replace('\', '\\').Replace('"', '\"')
    $Value = $Value.Replace("`r", '\r').Replace("`n", '\n').Replace("`t", '\t')
    return '"' + $Value + '"'
}

function ParseBackendMap([string]$Value) {
    $result = [ordered]@{}
    foreach ($raw in $Value.Split(';')) {
        $entry = $raw.Trim()
        if ($entry -eq '') { continue }
        $split = $entry.IndexOf('=')
        if ($split -lt 1 -or $split -eq $entry.Length - 1) { throw "Malformed backend entry '$entry'; expected id=host:port" }
        $id = $entry.Substring(0, $split).Trim()
        $endpoint = $entry.Substring($split + 1).Trim()
        if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9_.-]*$') { throw "Invalid backend ID '$id'" }
        if ($result.Contains($id)) { throw "Duplicate backend ID '$id'" }
        $match = [regex]::Match($endpoint, '^(\[[^\]]+\]|[^:\s]+):([0-9]+)$')
        if (-not $match.Success) { throw "Invalid backend endpoint '$endpoint'" }
        $port = 0
        if (-not [int]::TryParse($match.Groups[2].Value, [ref]$port) -or $port -lt 1 -or $port -gt 65535) {
            throw "Backend port is outside 1-65535 in '$endpoint'"
        }
        $result[$id] = $endpoint
    }
    if ($result.Count -eq 0) { throw 'At least one backend is required' }
    return $result
}

function ParseIdList([string]$Value, [System.Collections.IDictionary]$Known, [bool]$AllowEmpty = $false) {
    $result = New-Object System.Collections.Generic.List[string]
    foreach ($raw in $Value.Split(',')) {
        $id = $raw.Trim()
        if ($id -eq '') { continue }
        if (-not $Known.Contains($id)) { throw "Unknown backend ID '$id'" }
        if (-not $result.Contains($id)) { $result.Add($id) }
    }
    if (-not $AllowEmpty -and $result.Count -eq 0) { throw 'At least one backend ID is required' }
    return @($result)
}

function ReadExistingSecret([string]$Path, [string]$RegistryMode) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '' }
    $key = if ($RegistryMode -eq 'embedded') { 'embedded_shared_secret' } else { 'shared_secret' }
    $pattern = '^\s*' + [regex]::Escape($key) + '\s*=\s*"([0-9A-Fa-f]+)"\s*$'
    foreach ($line in [IO.File]::ReadAllLines($Path)) {
        $match = [regex]::Match($line, $pattern)
        if ($match.Success) { return $match.Groups[1].Value }
    }
    return ''
}

function NewRandomSecret() {
    $bytes = New-Object byte[] 32
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
    return (($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
}

function ResolveSecret([string]$PanelValue, [string]$ExistingValue, [string]$RegistryMode) {
    $value = $PanelValue.Trim()
    $placeholder = '^(?i)(change-me.*|paste.*secret.*|shared[-_ ]?secret|your[-_ ]?secret|replace[-_ ]?me.*)$'
    if ($value -match $placeholder) { throw 'The shared secret is a documented placeholder, not a usable secret' }
    if ($value -ne '') { return $value }
    if ($ExistingValue -ne '') { return $ExistingValue }
    if ($RegistryMode -eq 'embedded') { return NewRandomSecret }
    throw 'Remote Registry mode requires an explicit or previously saved shared secret'
}

function ParseBool([string]$Value, [string]$Name) {
    switch ($Value.Trim().ToLowerInvariant()) {
        'true' { return 'true' }
        'false' { return 'false' }
        default { throw "$Name must be true or false" }
    }
}

function ParsePort([string]$Value, [string]$Name) {
    $port = 0
    if (-not [int]::TryParse($Value, [ref]$port) -or $port -lt 1 -or $port -gt 65535) { throw "$Name must be from 1 through 65535" }
    return $port
}

function TomlArray([string[]]$Values) {
    return '[' + (($Values | ForEach-Object { TomlQuote $_ }) -join ', ') + ']'
}

function WriteAtomic([string]$Path, [string]$Content) {
    $directory = Split-Path -Parent $Path
    if ($directory -and -not (Test-Path -LiteralPath $directory)) { New-Item -ItemType Directory -Path $directory -Force | Out-Null }
    $temporary = Join-Path $directory ('.' + [IO.Path]::GetFileName($Path) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [IO.File]::WriteAllText($temporary, $Content, (New-Object Text.UTF8Encoding $false))
        Move-Item -LiteralPath $temporary -Destination $Path -Force
    }
    finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force }
    }
}

$bindAddress = Get-Value 'NP_BIND_ADDRESS' '0.0.0.0'
$serverPort = ParsePort (Get-Value 'NP_SERVER_PORT' '42420') 'Server port'
$registryPort = ParsePort (Get-Value 'NP_REGISTRY_PORT' '8765') 'Registry port'
$adminPort = ParsePort (Get-Value 'NP_ADMIN_PORT' '42499') 'Admin port'
$metricsPort = ParsePort (Get-Value 'NP_METRICS_PORT' '42500') 'Metrics port'
$maxPlayers = ParsePort (Get-Value 'NP_MAX_USERS' '100') 'Player limit'
$backends = ParseBackendMap (Get-Value 'NP_SERVERS' 'hub=127.0.0.1:42421')
$tryIds = ParseIdList (Get-Value 'NP_TRY' 'hub') $backends
$whitelistIds = ParseIdList (Get-Value 'NP_WHITELIST_SERVERS' '') $backends $true
$mode = (Get-Value 'NP_REGISTRY_MODE' 'embedded').Trim().ToLowerInvariant()
if (@('embedded', 'remote') -notcontains $mode) { throw 'Registry mode must be embedded or remote' }
$access = (Get-Value 'NP_REGISTRY_ACCESS' 'same-host').Trim().ToLowerInvariant()
if (@('same-host', 'other-hosts') -notcontains $access) { throw 'Registry access must be same-host or other-hosts' }
$registryUrl = (Get-Value 'NP_REGISTRY_URL' '').Trim()
if ($mode -eq 'remote' -and $registryUrl -notmatch '^https?://[^\s]+$') { throw 'Remote Registry mode requires an HTTP or HTTPS URL' }
$existingSecret = ReadExistingSecret $Target $mode
$secret = ResolveSecret (Get-Value 'NP_SHARED_SECRET' '') $existingSecret $mode
$embeddedBindHost = if ($access -eq 'same-host') { '127.0.0.1' } else { '0.0.0.0' }
$remoteSecret = if ($mode -eq 'remote') { $secret } else { '' }
$embeddedSecret = if ($mode -eq 'embedded') { $secret } else { '' }
$embeddedBind = if ($mode -eq 'embedded') { "http://${embeddedBindHost}:$registryPort" } else { '' }
$whitelistNetwork = ParseBool (Get-Value 'NP_WHITELIST_NETWORK' 'false') 'Network whitelist'
$verbose = ParseBool (Get-Value 'NP_VERBOSE' 'false') 'Verbose logging'

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add('bind = ' + (TomlQuote "${bindAddress}:$serverPort"))
$lines.Add('try = ' + (TomlArray $tryIds))
$lines.Add('')
$lines.Add('[servers]')
foreach ($entry in $backends.GetEnumerator()) { $lines.Add((TomlQuote $entry.Key) + ' = ' + (TomlQuote $entry.Value)) }
$lines.Add('')
$lines.Add('[transfers]')
$lines.Add('default_mode = "redirect"')
$lines.Add('allow_seamless = false')
$lines.Add('require_seamless_capability = true')
$lines.Add('fallback_to_redirect_when_seamless_unavailable = true')
$lines.Add('enable_unsafe_seamless_splice = false')
$lines.Add('')
$lines.Add('[admin]')
$lines.Add('bind = ' + (TomlQuote "127.0.0.1:$adminPort"))
$lines.Add('secret = ""')
$lines.Add('enabled = true')
$lines.Add('granted_permissions = ["*"]')
$lines.Add('')
$lines.Add('[registry]')
$lines.Add('mode = ' + (TomlQuote $mode))
$lines.Add('proxy_id = ' + (TomlQuote (Get-Value 'NP_PROXY_ID' 'nimbus-proxy')))
$lines.Add('url = ' + (TomlQuote $(if ($mode -eq 'remote') { $registryUrl } else { '' })))
$lines.Add('shared_secret = ' + (TomlQuote $remoteSecret))
$lines.Add('embedded_bind = ' + (TomlQuote $embeddedBind))
$lines.Add('embedded_shared_secret = ' + (TomlQuote $embeddedSecret))
$lines.Add('backend_stale_seconds = 20')
$lines.Add('backend_drop_seconds = 120')
$lines.Add('nonce_window_seconds = 90')
$lines.Add('max_reservation_ttl_seconds = 300')
$lines.Add('fail_on_error = true')
$lines.Add('transfer_intent_poll_ms = 1000')
$lines.Add('advertise_on_master_server = false')
$lines.Add('')
$lines.Add('[whitelist]')
$lines.Add('network = ' + $whitelistNetwork)
$lines.Add('servers = ' + (TomlArray $whitelistIds))
$lines.Add('fail_open_until_first_sync = false')
$lines.Add('')
$lines.Add('[logging]')
$lines.Add('verbose = ' + $verbose)
$lines.Add('sniff_frames = false')
$lines.Add('log_traffic_bytes = false')
$lines.Add('')
$lines.Add('[metrics]')
$lines.Add('enabled = true')
$lines.Add('bind = ' + (TomlQuote "http://127.0.0.1:$metricsPort"))
$lines.Add('path = "/metrics"')
$lines.Add('status_api = true')
$lines.Add('status_api_token = ""')
$lines.Add('')
$lines.Add('[status]')
$lines.Add('enabled = true')
$lines.Add('name = ' + (TomlQuote (Get-Value 'NP_STATUS_NAME' 'Nimbus')))
$lines.Add('motd = ' + (TomlQuote (Get-Value 'NP_STATUS_MOTD' 'Vintage Story proxy')))
$lines.Add('game_mode = "survival"')
$lines.Add('password = false')
$lines.Add('server_version = ""')
$lines.Add('max_players = ' + $maxPlayers)
$lines.Add('query_timeout_ms = 1500')
$lines.Add('')
$lines.Add('[plugins]')
$lines.Add('enabled = true')
$lines.Add('directory = "plugins"')
$lines.Add('disabled = []')
$lines.Add('')
$lines.Add('[persistence]')
$lines.Add('persist_drain_flags = true')
$lines.Add('drain_flags_file = "nimbus.drain-state.json"')
$lines.Add('')
$lines.Add('[advanced]')
$lines.Add('connect_timeout_ms = 5000')
$lines.Add('buffer_size = 16384')

WriteAtomic $Target (($lines -join "`n") + "`n")
Write-Output "wrote $Target"
